use std::{env, fs, path::PathBuf};
use gammaloop_api::{commands::set::SetArgs, state::State};
use gammalooprs::{graph::GroupId, initialisation::initialise,
    integrands::process::GaussianReferenceFunction};
use figment::{Figment, providers::Serialized};

fn main() -> color_eyre::Result<()> {
    initialise()?;
    let args = env::args().skip(1).collect::<Vec<_>>();
    assert_eq!(args.len(), 4, "state overlay points_per_channel output_prefix");
    let mut state = State::load(PathBuf::from(&args[0]), None, None)?;
    state.activate_loaded_integrand_backends(false)?;
    let integrand = state.process_list.get_integrand_mut(0, "default")?;
    let input = SetArgs::String { string: fs::read_to_string(&args[1])? };
    let settings = input.merge_figment(Figment::from(Serialized::defaults(integrand.get_settings())))?.extract()?;
    *integrand.get_mut_settings() = settings;
    std::thread::scope(|scope| -> color_eyre::Result<()> {
        std::thread::Builder::new().stack_size(64*1024*1024)
            .spawn_scoped(scope, || integrand.warm_up(&state.model))?.join().unwrap()
    })?;
    fs::write(format!("{}.settings.toml", args[3]), toml::to_string_pretty(integrand.get_settings())?)?;
    assert_eq!(integrand.group_orientation_count(GroupId(0)), Some(18));
    let parameterization = integrand.get_settings().sampling.get_parameterization_settings().unwrap();
    let ids = integrand.group_sampling_channel_ids(GroupId(0), &parameterization)?;
    let n: usize = args[2].parse()?;
    // Same deterministic quadrature as the saved-state acceptance regression.
    let coordinates = (1..=n).map(|index| [2,3,5,7,11,13].map(|base| {
        let (mut index, mut fraction, mut value) = (index, 1.0, 0.0);
        while index > 0 { fraction /= base as f64; value += (index % base) as f64 * fraction; index /= base; }
        value
    }).to_vec()).collect::<Vec<_>>();
    let reference = GaussianReferenceFunction::new(1.2, vec![0.4,-0.3,0.2,-0.2,0.1,0.35])?;
    let (mut normalization, mut moment, mut expected_moment) = (0.0,0.0,0.0);
    let mut reports = Vec::new();
    for id in ids {
        let report = integrand.evaluate_reference_discrete_coordinates(&[0,id.0], &coordinates, &reference)?;
        assert_eq!(report.finite_sample_count, n);
        normalization += report.normalization;
        moment += report.second_moment;
        expected_moment = report.expected_second_moment;
        reports.push(format!("{{\"channel\":{},\"normalization\":{},\"second_moment\":{},\"finite_samples\":{},\"dispersion\":{}}}",
            id.0, report.normalization, report.second_moment, report.finite_sample_count, report.normalization_stderr));
    }
    // Per-channel unit-weight contributions sum to the full integral. No
    // addition of their correlated per-draw dispersions is interpreted as MC error.
    let passed = (normalization-1.0).abs() < 0.02 && (moment-expected_moment).abs() < 0.2;
    let report = format!("{{\"passed\":{passed},\"orientation_count\":18,\"points_per_channel\":{n},\"normalization\":{normalization},\"second_moment\":{moment},\"expected_second_moment\":{expected_moment},\"channels\":[{}]}}\n", reports.join(","));
    fs::write(format!("{}.json", args[3]), &report)?;
    print!("{report}");
    assert!(passed, "existing normalized-reference acceptance tolerances failed");
    Ok(())
}

